class Solution:
    def minEatingSpeed(self, piles: List[int], h: int) -> int:
        # the monotonicity here is the time/speed
        # speed increasing, time decreasing
        # max speed is the biggest pile because that what KOKO can do
        # min is 1
        low, high = 1, max(piles)
        ans = -1
        while low <= high:
            speed = (high + low) // 2
            time = 0
            for p in piles:
                time += ceil(p/speed)
            if time <= h:
                ans = speed
                high = speed - 1
            else:
                low = speed + 1
        return ans
